 "content": "def transform(grid):
    """Combine two binary panels separated by a uniform divider.

    The panels share their background color. Mark a cell with 3 when both
    panels mark that position; otherwise retain their shared background.
    """
    h, w = len(grid), len(grid[0])
    # Find the solid separator row or column.
    sep = None
    axis = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            sep, axis = r, 0
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                sep, axis = c, 1
                break
    if sep is None:
        raise ValueError("No uniform separator found")

    if axis == 0:
        a, b = grid[:sep], grid[sep + 1:]
        if len(a) != len(b) or any(len(x) != len(y) for x, y in zip(a, b)):
            raise ValueError("Panels do not have matching dimensions")
        colors = set(v for row in a for v in row) & set(v for row in b for v in row)
        # The shared color is the common background of the two binary panels.
        bg = max(colors, key=lambda c: sum(v == c for row in a for v in row) + sum(v == c for row in b for v in row))
        return [[3 if x != bg and y != bg else bg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    else:
        a = [row[:sep] for row in grid]
        b = [row[sep + 1:] for row in grid]
        if any(len(x) != len(y) for x, y in zip(a, b)):
